<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Deposit', href: '/owner/deposits' }] };
</script>

<script lang="ts">
    import { Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    type Deposit = { id: number; required_amount_rupiah: number; received_rupiah: number; balance_rupiah: number; resident: { full_name: string; whatsapp_number: string } | null; property: { name: string } | null; room: { code: string } | null; booking_id: number | null; tenancy_id: number | null; settlement_status: string | null };
    type Page<T> = { data: T[]; links: { url: string | null; label: string; active: boolean }[]; from: number | null; to: number | null; total: number };
    let { deposits }: { deposits: Page<Deposit> } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
</script>

<AppHead title="Deposit jaminan" />
<main class="space-y-6 p-4 md:p-8">
    <header class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Keuangan</p><h1 class="text-3xl font-semibold tracking-tight">Deposit jaminan</h1><p class="max-w-3xl text-sm text-muted-foreground">Deposit termasuk uang muka booking dan tetap dicatat sebagai kewajiban, bukan pendapatan sewa.</p></header>
    <section class="overflow-hidden rounded-xl border bg-card shadow-sm" aria-label="Akun deposit">{#if deposits.data.length === 0}<div class="p-10 text-center"><h2 class="font-medium">Belum ada akun deposit</h2><p class="mt-1 text-sm text-muted-foreground">Akun dibuat saat booking atau check-in dicatat.</p></div>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[56rem] text-left text-sm"><thead class="border-b bg-muted/40 text-muted-foreground"><tr><th class="px-5 py-3 font-medium">Penyewa</th><th class="px-5 py-3 font-medium">Properti / kamar</th><th class="px-5 py-3 text-right font-medium">Nominal disepakati</th><th class="px-5 py-3 text-right font-medium">Kas deposit diterima</th><th class="px-5 py-3 text-right font-medium">Saldo liability</th><th class="px-5 py-3 font-medium">Settlement</th><th class="px-5 py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each deposits.data as deposit (deposit.id)}<tr><td class="px-5 py-4"><p class="font-medium">{deposit.resident?.full_name ?? '—'}</p><p class="text-xs text-muted-foreground">{deposit.resident?.whatsapp_number ?? ''}</p></td><td class="px-5 py-4"><p>{deposit.property?.name ?? '—'}</p><p class="text-xs text-muted-foreground">{deposit.room ? `Kamar ${deposit.room.code}` : '—'}</p></td><td class="px-5 py-4 text-right">{money(deposit.required_amount_rupiah)}</td><td class="px-5 py-4 text-right">{money(deposit.received_rupiah)}</td><td class="px-5 py-4 text-right font-medium">{money(deposit.balance_rupiah)}</td><td class="px-5 py-4">{deposit.settlement_status ?? 'Belum diselesaikan'}</td><td class="px-5 py-4 text-right"><Link href={`/owner/deposits/${deposit.id}`} class="text-primary underline-offset-4 hover:underline">Detail</Link></td></tr>{/each}</tbody></table></div><footer class="flex flex-wrap items-center justify-between gap-4 border-t px-5 py-4 text-sm"><p class="text-muted-foreground">Menampilkan {deposits.from ?? 0}–{deposits.to ?? 0} dari {deposits.total} akun</p><nav aria-label="Navigasi halaman" class="flex flex-wrap gap-1">{#each deposits.links as link, index (index)}{#if link.url}<Link href={link.url} class={`rounded border px-3 py-1.5 ${link.active ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}>{link.label}</Link>{:else}<span class="rounded border px-3 py-1.5 text-muted-foreground">{link.label}</span>{/if}{/each}</nav></footer>{/if}</section>
</main>
